-- Member ids are UUIDv7 generated by the database (ADR 0007), in the member table and in every column that holds one.
-- Ids handed out so far (the demo members of a development database) become fixed UUIDs: 0197a000-0000-7000-8000-<id>.
ALTER TABLE member ALTER COLUMN id DROP IDENTITY;
ALTER TABLE member ALTER COLUMN id TYPE UUID
    USING ('0197a000-0000-7000-8000-' || lpad(id::text, 12, '0'))::uuid;
ALTER TABLE member ALTER COLUMN id SET DEFAULT uuidv7();

ALTER TABLE group_membership ALTER COLUMN member_id TYPE UUID
    USING ('0197a000-0000-7000-8000-' || lpad(member_id::text, 12, '0'))::uuid;
ALTER TABLE rsvp ALTER COLUMN member_id TYPE UUID
    USING ('0197a000-0000-7000-8000-' || lpad(member_id::text, 12, '0'))::uuid;
